using System;
using System.Collections.Generic;
sealed class ExpeditionItemDefinition {
 public string Key,Name,Kind;public int Index,Tier;
 public static List<ExpeditionItemDefinition> All(){var items=new List<ExpeditionItemDefinition>();void Add(string key,string name,string kind,int index,int tier){items.Add(new(){Key=key,Name=name,Kind=kind,Index=index,Tier=tier});}for(int i=0;i<ExpeditionGame.GunNames.Length;i++)Add("weapon/"+i,ExpeditionGame.GunNames[i],"weapon",i,ExpeditionGame.GunTier(i));foreach(var r in ExpeditionRecipe.All)if(r.Kind=="armor")Add("armor/"+r.Tier+"/"+r.Result,r.Name,"armor",r.Result,r.Tier);for(int i=0;i<7;i++)Add("material/"+i,ExpeditionGame.ResourceNames[i],"material",i,i<3?1:i-1);Add("bandage","Bandage roll","bandage",0,1);Add("food","Trail provisions","food",0,1);Add("water","Drinking water","water",0,1);Add("bag","Sleeping bag kit","bag",0,2);for(int type=0;type<5;type++)Add(type==0?"ammo":"ammo/"+type,ExpeditionGame.AmmoNames[type],"ammo",type,type==4?5:type>=2?3:2);Add("legendary","Legendary heart","legendary",0,5);Add("legendary-upgrade","Legendary ascension","legendary",50,5);Add("millcore","Foreman core","millcore",0,2);Add("mill-temper","Foreman weapon tempering","mill",1,2);Add("catalyst","Night catalyst","catalyst",0,3);Add("tuning","Nocturnal tuning module","tuning",0,3);for(int i=1;i<=5;i++)Add("bench/"+i,ExpeditionRecipe.All[i-1].Name,"bench",i,i);for(int i=0;i<BuildDefinition.All.Length;i++)Add("build/"+i,BuildDefinition.All[i].Name,"build",i,BuildDefinition.All[i].Tier);foreach(var r in ExpeditionRecipe.All)if(r.Kind is "weapon-mod" or "medicine" or "arrow" or "attachment" or "fuel" or "survival-tech")Add(r.Kind+"/"+r.Tier+"/"+r.Result,r.Name,r.Kind,r.Result,r.Tier);Add("axe","Field axe / T","tool",0,1);Add("shovel","Earthwork shovel / P O","tool",1,1);Add("hammer","Builder hammer / B","tool",2,1);for(int i=0;i<6;i++)Add("hunting-material/"+i,ExpeditionGame.HuntNames[i],"hunting-material",i,1);Add("hunting-gear/hood","Rabbit-fur hood","armor",11,1);Add("hunting-gear/boots","Leather hunting boots","armor",13,2);Add("hunting-gear/vest","Fur-lined woodland vest","armor",0,2);Add("hunting-tool/1","Flint skinning knife","hunting-tool",1,1);Add("hunting-tool/2","Stone butcher cleaver","hunting-tool",2,1);return items;}
}
